    const { mode } = this.state
    if (mode === 'PLAYING') {
      await this.handleMove('R')
    } else {
      console.warn('Ignoring event R because mode is', mode)
    }
  }

  handleDown = async () => {
    const { mode } = this.state
    if (mode === 'PLAYING') {
      await this.handleMove('D')
