handleReplayTimeout = async () => {
    const {
      replayTimeout
    } = this.props

    const {
      mode,
      replay,
      wellStateId
    } = this.state

    let nextReplayTimeoutId
    let nextMode: Mode = mode  // need the Mode type

    if (mode === 'REPLAYING') {
      await this.handleRedo()

      if (wellStateId + 1 in replay) {
        nextReplayTimeoutId = setTimeout(this.handleReplayTimeout, replayTimeout)
      } else if (this.state.mode !== 'GAME_OVER') {
        // no more inputs in replay: hand control back to the player
        nextMode = 'PLAYING'
      }
    } else {
      console.warn('Ignoring input replay step because mode is', mode)
    }

    this.setState({
      mode: nextMode,
      replayTimeoutId: nextReplayTimeoutId
    })
  }
```

Wait, be careful: if the replay runs out AND the game is over, mode should stay as GAME_OVER. Since handleMove already sets the mode to GAME_OVER, after the redo `this.state.mode` will be the correct one. So:

```ts
